examples.sql:
select table_schema, table_name
from information_schema.tables
order by 1, 2;

select id, first_name, country
from jaffle_shop.customers
limit 5;

select id, user_id, order_date, status
from jaffle_shop.orders
where status = 'returned';

select id, first_name, email
from jaffle_shop.customers
where email is null;

select id, first_name, coalesce(email, 'no email') as email
from jaffle_shop.customers
where id in (15, 17, 34);

select distinct status
from jaffle_shop.orders
order by status;

select status, user_id, count(*)
from jaffle_shop.orders
group by status;

select country, n
from (
    select country, count(*) as n
    from jaffle_shop.customers
    group by country
) as by_country
where n >= 15
order by n desc;

select id, user_id
from jaffle_shop.orders
where row_number() over (partition by user_id order by order_date desc) = 1;

create schema sandbox;

create table sandbox.daily_revenue as
select
    created as payment_date,
    sum(amount) as revenue_cents
from stripe.payments
where status = 'success'
group by created;

select count(*) as n_days, sum(revenue_cents) / 100 as total_revenue
from sandbox.daily_revenue;

create table sandbox.status_log as
select id as order_id, status from jaffle_shop.orders where id <= 3;

insert into sandbox.status_log
select id, status from jaffle_shop.orders where id <= 3;

select order_id, count(*) as n_copies
from sandbox.status_log group by order_id order by order_id;

create table sandbox.order_status (
    order_id integer primary key,
    status   varchar not null
);

insert into sandbox.order_status
select id, status from jaffle_shop.orders where id <= 3;

select * from sandbox.order_status order by order_id;

create table sandbox.status_updates as
select * from (values (2, 'returned'), (4, 'completed')) as t(order_id, status);

merge into sandbox.order_status as target
using sandbox.status_updates as updates
    on target.order_id = updates.order_id
when matched then
    update set status = updates.status
when not matched then
    insert (order_id, status) values (updates.order_id, updates.status);

select * from sandbox.order_status order by order_id;

create table sandbox.orders_copy as
select * from jaffle_shop.orders;

create view sandbox.order_count_view as
select count(*) as n_orders from sandbox.orders_copy;

create table sandbox.order_count_table as
select count(*) as n_orders from sandbox.orders_copy;

-- a new order arrives
insert into sandbox.orders_copy (id, user_id, order_date, status, _loaded_at)
values (301, 7, '2026-01-02', 'placed', '2026-01-02 09:00:00');

select
    (select n_orders from sandbox.order_count_view)  as from_view,
    (select n_orders from sandbox.order_count_table) as from_table;

select
    (select count(*) from (select * from scratch.legacy_result except select * from scratch.refactored_result)) as legacy_only,
    (select count(*) from (select * from scratch.refactored_result except select * from scratch.legacy_result)) as refactored_only;

select count(*) as n_rows, count(distinct o.id) as n_orders
from jaffle_shop.orders as o
inner join stripe.payments as p on o.id = p.orderid;
